-- composition of rule kernels distinct_aggregate_rewrite x redundant_order_keys (duckdb), template not_exists
SELECT count(*) FROM (SELECT '2000-01-01 00:00:00+00'::timestamptz AS c0, 1.5::numeric AS c1, (- CASE WHEN FALSE THEN (SELECT SUM (DISTINCT a2.c1) FROM t2 AS a2) ELSE 2.25::numeric END) AS c2, 10 AS c3 FROM t1 AS a1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT '2000-01-01 00:00:00+00'::timestamptz AS c0, 1.5::numeric AS c1, (- CASE WHEN FALSE THEN (SELECT SUM (DISTINCT a2.c1) FROM t2 AS a2) ELSE 2.25::numeric END) AS c2, 10 AS c3 FROM t1 AS a1) AS ka) ELSE 0 END
